    address sender;
    address pool;
    IERC20[] tokens;
    uint256[] exactAmountsIn;
    uint256 minBptAmountOut;
    bool wethIsEth;
    bytes userData;
}

/**
 * @notice Data for the swap hook.
 * @param sender Account initiating the swap operation
