 */
struct RemoveLiquidityHookParams {
    address sender;
    address pool;
    uint256[] minAmountsOut;
    uint256 maxBptAmountIn;
    RemoveLiquidityKind kind;
    bool wethIsEth;
    bytes userData;
}

